#
# t_phase3_dyson.jl
#
# To compare the Dyson solvers with NESSi, point by point. The data are
# generated by .nessi/kbref/p3_dyson_ref.cpp, whose closed-form inputs are
# rebuilt here with exactly the same formulas (nothing is read back from
# the output).
#
# NESSi reference: libcntr/cntr/cntr_dyson_impl.hpp:451-1736.
#
# Primary gate: every entry with atol = rtol = 1e-10.
#

using LinearAlgebra

const P3_DATA = joinpath(@__DIR__, "data", "phase3")

#
# Authoritative 2x2 case, see p3_dyson_ref.cpp
#
const NC_NT = 20
const NC_NTAU = 40
const NC_BETA = 2.0
const NC_H = 0.05
const NC_MU = 0.2

const NC_A = C64[0.5 0.3-0.2im; 0.3+0.2im -0.4]
const NC_B = C64[0.1 0.25im; -0.25im 0.6]

nc_ham(t) = (1.0 + 0.3 * sin(t)) * NC_A + (0.5 + 0.2 * cos(1.3 * t)) * NC_B

nc_sigma_mat(τ) = 0.1 * C64[-0.5*exp(-τ) 0.2+0.1im*τ/NC_BETA;
                            -0.15+0.05im -0.3*exp(-0.5τ)]
nc_sigma_ret(t, t′) = 0.1 * C64[-im*cos(t-t′) 0.2*exp(-im*(t-0.5t′));
                                -0.1+0.3im*sin(t+t′) -0.5im*exp(-0.3(t-t′))]
nc_sigma_tv(t, τ) = 0.1 * C64[0.3im*exp(-τ)*cos(t) 0.1+0.2im*t;
                              -0.2*exp(-0.5τ) 0.4im*sin(t+τ)]
nc_sigma_les(t′, t) = 0.1 * C64[0.2im*cos(t-t′) 0.1+0.1im*t′;
                                -0.3+0.05im*t 0.25im]

function nc_build()
    C = Cn(NC_NT + 1, NC_NTAU + 1, 2, 2, NC_NT * NC_H, NC_BETA)
    δτ = NC_BETA / NC_NTAU
    H = Cf(NC_NT + 1, 2, 2)
    H[0] = nc_ham(0.0)
    for n = 0:NC_NT
        H[n+1] = nc_ham(n * NC_H)
    end
    Σ = ℱ(C, FERMI)
    for q = 0:NC_NTAU
        Σ.mat[q+1] = nc_sigma_mat(q * δτ)
    end
    for i = 0:NC_NT
        for j = 0:i
            Σ.ret[i+1, j+1] = nc_sigma_ret(i * NC_H, j * NC_H)
        end
        for q = 0:NC_NTAU
            Σ.lmix[i+1, q+1] = nc_sigma_tv(i * NC_H, q * δτ)
        end
        for j = i:NC_NT
            Σ.less[i+1, j+1] = nc_sigma_les(i * NC_H, j * NC_H)
        end
    end
    return C, H, Σ
end

#
# Embedding model: H = eps1, Σ = lam² g2
#
const EM_LAM = 0.5

function em_build(nt, ntau, sign, eps1, eps2, μ, β, h)
    C = Cn(max(nt, 1) + 1, ntau + 1, 1, 1, max(nt, 1) * h, β)
    H = Cf(getntime(C), 1, 1)
    for n = 0:getntime(C)
        H[n] = fill(C64(eps1), 1, 1)
    end
    Σ = ℱ(C, sign)
    green_from_H!(Σ, μ, fill(C64(eps2), 1, 1), β, h)
    for s in (:mat, :ret, :lmix, :less)
        getfield(Σ, s).data .*= EM_LAM^2
    end
    return C, H, Σ
end

#
# Compare only the Matsubara entries (the real time entries of the
# reference are zero)
#
function p3_test_mat(G::ℱ, ref)
    nfail = 0
    err = 0.0
    for row in ref.rows
        if row.component == "mat"
            v = G.mat[row.i+1][row.a+1, row.b+1]
            err = max(err, abs(v - row.value))
            isapprox(v, row.value; atol = 1e-10, rtol = 1e-10) || (nfail += 1)
        else
            @test row.value == 0.0
        end
    end
    @test nfail == 0
    return err
end

function p3_report(name, errs)
    @printf("  %-32s max err: mat %.2e ret %.2e tv %.2e les %.2e\n",
            name, errs["mat"], errs["ret"], errs["tv"], errs["les"])
end

@testset verbose = true "NESSi: phase 3 dyson" begin
    @testset "Matsubara (embedding)" begin
        ntau, k, β = 100, 5, 5.0
        for (name, sign, method, eps1, eps2, μ) in
                (("dyson_mat_fixpoint_fermion", FERMI, :fixpoint, -1.0, 1.0, 0.1),
                 ("dyson_mat_cg_fermion", FERMI, :cg, -1.0, 1.0, 0.1),
                 ("dyson_mat_cg_boson", BOSE, :cg, 1.0, 2.0, -0.5))
            ref = read_kbref(joinpath(P3_DATA, name * ".dat"))
            @test ref.metadata["case"] == name
            @test parse(Int, ref.metadata["ntau"]) == ntau
            @test parse(Int, ref.metadata["sig"]) == sign
            @test ref.metadata["method"] == String(method)
            C, H, Σ = em_build(0, ntau, sign, eps1, eps2, μ, β, 1.0)
            G = ℱ(C, sign)
            dyson_mat!(G, Σ, μ, H, β; solve_order = k, method = method)
            err = p3_test_mat(G, ref)
            @printf("  %-32s max err: mat %.2e\n", name, err)
        end
    end

    @testset "authoritative 2x2 (k = $k)" for k = 1:5
        C, H, Σ = nc_build()
        #
        # Matsubara + start-up
        G = ℱ(C, FERMI)
        dyson_mat!(G, Σ, NC_MU, H, NC_BETA; solve_order = k, method = :fixpoint)
        dyson_start!(G, NC_MU, H, Σ, NC_BETA, NC_H; solve_order = k)
        ref = read_kbref(joinpath(P3_DATA, "dyson_ncomm2x2_start_k$k.dat"))
        @test parse(Int, ref.metadata["solve_order"]) == k
        p3_report("dyson_ncomm2x2_start_k$k", test_kbref(G, ref))
        #
        # First BDF time step and two more
        for nkb = k+2:k+4
            dyson_timestep!(nkb, G, NC_MU, H, Σ, NC_BETA, NC_H; solve_order = k)
        end
        ref = read_kbref(joinpath(P3_DATA, "dyson_ncomm2x2_timestep_k$k.dat"))
        p3_report("dyson_ncomm2x2_timestep_k$k", test_kbref(G, ref))
        #
        # Full solution
        F = ℱ(C, FERMI)
        dyson!(F, NC_MU, H, Σ, NC_BETA, NC_H; solve_order = k)
        ref = read_kbref(joinpath(P3_DATA, "dyson_ncomm2x2_full_k$k.dat"))
        p3_report("dyson_ncomm2x2_full_k$k", test_kbref(F, ref))
        #
        # All four orbital elements carry signal
        for a = 1:2, b = 1:2
            @test abs(F.less[NC_NT ÷ 2 + 1, NC_NT + 1][a, b]) > 1e-6
            @test abs(F.lmix[2, NC_NTAU ÷ 2 + 1][a, b]) > 1e-6
        end
    end

    @testset "embedding 1x1 (k = 5)" begin
        nt, ntau, k, β, h, μ = 30, 50, 5, 5.0, 0.05, -0.1
        C, H, Σ = em_build(nt, ntau, FERMI, -1.0, 1.0, μ, β, h)
        G = ℱ(C, FERMI)
        dyson_mat!(G, Σ, μ, H, β; solve_order = k)
        dyson_start!(G, μ, H, Σ, β, h; solve_order = k)
        p3_report("dyson_embedding_1x1_start",
                  test_kbref(G, read_kbref(joinpath(P3_DATA, "dyson_embedding_1x1_start.dat"))))
        for nkb = k+2:k+4
            dyson_timestep!(nkb, G, μ, H, Σ, β, h; solve_order = k)
        end
        p3_report("dyson_embedding_1x1_timestep",
                  test_kbref(G, read_kbref(joinpath(P3_DATA, "dyson_embedding_1x1_timestep.dat"))))
        F = ℱ(C, FERMI)
        dyson!(F, μ, H, Σ, β, h; solve_order = k)
        p3_report("dyson_embedding_1x1_full",
                  test_kbref(F, read_kbref(joinpath(P3_DATA, "dyson_embedding_1x1_full.dat"))))
        #
        # Additional report: the exact (1,1) element of the 2x2 model
        C2 = Cn(nt + 1, ntau + 1, 2, 2, nt * h, β)
        G2 = ℱ(C2, FERMI)
        green_from_H!(G2, μ, C64[-1.0 EM_LAM; EM_LAM 1.0], β, h)
        err = 0.0
        for n = 1:nt+1, j = 1:n
            err = max(err, abs(F.ret[n, j][1,1] - G2.ret[n, j][1,1]),
                      abs(F.less[j, n][1,1] - G2.less[j, n][1,1]))
        end
        @test err < 1e-3
        @printf("  %-32s error to the exact 2x2 model: %.2e\n", "dyson_embedding_1x1_full", err)
    end
end
